/** @vitest-environment jsdom */
import { afterEach, beforeEach, expect, it, vi } from 'vitest';
import { act, cleanup, fireEvent, render, screen, waitFor } from '@testing-library/react';
import Home from './page';
import { useExecutionStore } from '@/lib/store';

const navigation = vi.hoisted(() => ({ params: new URLSearchParams('template=strategy_analysis') }));
vi.mock('next/navigation', () => ({ useRouter: () => ({ push: vi.fn(), replace: vi.fn() }), useSearchParams: () => navigation.params }));
vi.mock('@/lib/i18n', () => ({ useLanguage: () => ({ language: 'en', t: (k: string) => k }) }));
vi.mock('@/components/Settings', () => ({ useSettings: () => ({ settings: { providers: {}, preferences: { defaultExportMode: 'governance' } }, isLoaded: true }) }));
vi.mock('@/lib/analytics', () => ({ trackEvent: vi.fn() }));
vi.mock('@/lib/enforcement-log', () => ({ logEnforcementDecision: vi.fn() }));
vi.mock('@/lib/skill-template-map', () => ({ getSkillForTemplate: () => null }));
vi.mock('@/components/SpecExport', () => ({ SpecExport: () => null }));
vi.mock('@/lib/hooks/useExecute', () => {
    const fetchProviders = () => undefined;
    return { useProviders: () => ({ providers: [], anyConfigured: false, fetchProviders }) };
});
vi.mock('@/components/home/HomeBrowseExperience', () => ({ HomeBrowseExperience: () => null }));
vi.mock('@/components', async () => {
    const a = await vi.importActual<typeof import('@/components/DynamicForm')>('@/components/DynamicForm');
    const b = await vi.importActual<typeof import('@/components/ProcessingScreen')>('@/components/ProcessingScreen');
    const c = await vi.importActual<typeof import('@/components/ResultViewer')>('@/components/ResultViewer');
    const leaf = () => null;
    return { DynamicForm: a.DynamicForm, ProcessingScreen: b.ProcessingScreen, ResultViewer: c.ResultViewer,
        TemplatePreviewModal: leaf, OnboardingTour: leaf, AppBuilderWizard: leaf, ProductDesignWizard: leaf,
        MarketingCampaignWizard: leaf, BusinessStrategyWizard: leaf, SecurityAssessmentWizard: leaf,
        ResearchProjectWizard: leaf, SystemDesignWizard: leaf, ContentStrategyWizard: leaf, DataAnalysisWizard: leaf };
});
type Payload = { templateId: string; inputs: Record<string, string>; intent: string };
let requests: { payload: Payload; finish: (output: string) => void }[];
let urls: string[];
let transport: ReturnType<typeof vi.spyOn>;
beforeEach(() => {
    localStorage.clear(); sessionStorage.clear();
    useExecutionStore.setState({ executions: [], currentExecution: null });
    requests = []; urls = [];
    transport = vi.spyOn(globalThis, 'fetch').mockImplementation((url, init) => {
        urls.push(String(url));
        if (String(url) !== '/api/execute') throw new Error('Unexpected Local probe URL');
        const payload = JSON.parse(String(init?.body)) as Payload;
        return new Promise<Response>(resolve => requests.push({ payload, finish: output => resolve(new Response(JSON.stringify({ success: true, output }), { status: 200 })) }));
    });
});
afterEach(() => { cleanup(); transport.mockRestore(); vi.restoreAllMocks(); });
it('binds the actual strategy form and displayed parent despite a newer unrelated execution', async () => {
    render(<Home />);
    await waitFor(() => expect(document.querySelector('[name="topic"]')).toBeTruthy());
    const input = { topic: 'LOCAL_REGIONAL_STRATEGY_47', context: 'LOCAL_CONTEXT_82' };
    for (const [name, value] of Object.entries(input)) fireEvent.change(document.querySelector(`[name="${name}"]`)!, { target: { value } });
    fireEvent.click(screen.getByRole('button', { name: 'Preview agent instructions' }));
    const intent = document.querySelector('pre')!.textContent!;
    expect(intent).toContain(input.topic); expect(intent).toContain(input.context);
    await act(async () => { fireEvent.submit(document.querySelector('form')!); });
    await waitFor(() => expect(requests).toHaveLength(1));
    expect(requests[0].payload).toMatchObject({ templateId: 'strategy_analysis', inputs: input, intent });
    const parent = useExecutionStore.getState().executions[0];
    expect(parent.input).toEqual(input);
    await act(async () => requests[0].finish('LOCAL_PARENT_196'));
    await waitFor(() => expect(screen.getByTestId('deliverable-pack-preview').textContent).toContain('LOCAL_PARENT_196'));
    await act(async () => useExecutionStore.getState().addExecution({ ...parent, id: 'LOCAL_DECOY_705', output: 'WRONG_DECOY_OUTPUT', intent: 'WRONG_DECOY_INTENT', input: { topic: 'WRONG_DECOY_INPUT' }, status: 'completed' }));
    expect(useExecutionStore.getState().executions[0].id).toBe('LOCAL_DECOY_705');
    expect(screen.getByTestId('deliverable-pack-preview').textContent).toContain('LOCAL_PARENT_196');
    fireEvent.change(screen.getByTestId('followup-input'), { target: { value: 'LOCAL_REFINEMENT_638' } });
    fireEvent.click(screen.getByTestId('followup-submit-btn'));
    await waitFor(() => expect(requests).toHaveLength(2));
    const child = useExecutionStore.getState().executions[0];
    expect(child.parentExecutionId).toBe(parent.id);
    expect(child.parentExecutionId).not.toBe('LOCAL_DECOY_705');
    expect(child.input).toEqual({ ...input, _previousOutput: 'LOCAL_PARENT_196' });
    expect(requests[1].payload).toMatchObject({ templateId: 'strategy_analysis', inputs: { ...input, _previousOutput: 'LOCAL_PARENT_196' }, intent: 'LOCAL_REFINEMENT_638' });
    await act(async () => requests[1].finish('LOCAL_CHILD_284'));
    await waitFor(() => expect(screen.getByTestId('deliverable-pack-preview').textContent).toContain('LOCAL_CHILD_284'));
    expect(screen.getByTestId('deliverable-pack-preview').textContent).toContain('LOCAL_REFINEMENT_638');
    expect(screen.queryByText('LOCAL_PARENT_196')).toBeNull();
    expect(screen.queryByText('WRONG_DECOY_OUTPUT')).toBeNull();
    expect(useExecutionStore.getState().currentExecution?.id).toBe(child.id);
    expect(useExecutionStore.getState().executions.find(e => e.id === parent.id)?.output).toBe('LOCAL_PARENT_196');
    expect(useExecutionStore.getState().executions.find(e => e.id === 'LOCAL_DECOY_705')?.output).toBe('WRONG_DECOY_OUTPUT');
    expect(urls).toEqual(['/api/execute', '/api/execute']);
});
